// archivo: salescontroller.cs
// función: controla las ventas y la salida de productos del inventario.

using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using AbarrotesInventory.Application.Interfaces;using AbarrotesInventory.Domain.Entities;using AbarrotesInventory.Infrastructure.Data;using Microsoft.EntityFrameworkCore;
// espacio de nombres que organiza las clases del proyecto.
namespace AbarrotesInventory.Web.Controllers;[Authorize] public class SalesController(IInventoryService s,AppDbContext db):Controller { public async Task<IActionResult> Index()=>View(await db.Sales.Include(x=>x.Customer).Include(x=>x.User).OrderByDescending(x=>x.Date).ToListAsync()); [HttpGet] public async Task<IActionResult> Create(){ViewBag.Products=await s.GetProductsAsync();ViewBag.Customers=await s.GetCustomersAsync();return View();}[HttpPost] public async Task<IActionResult> Create(int customerId,string paymentMethod,int productId,int quantity){try{var u=await db.Users.FirstAsync(x=>x.Username==User.Identity!.Name);var p=await s.GetProductAsync(productId)??throw new Exception("Producto no existe");var sale=new Sale{Number="V-"+DateTime.Now.ToString("yyyyMMddHHmmssfff"),CustomerId=customerId,UserId=u.Id,PaymentMethod=paymentMethod,Tax=0};sale.Details.Add(new SaleDetail{ProductId=productId,Quantity=quantity,UnitPrice=p.SalePrice});await s.RegisterSaleAsync(sale); db.Payments.Add(new Payment{SaleId=sale.Id,Amount=sale.Total,Method=paymentMethod,Date=DateTime.Now}); await db.SaveChangesAsync(); TempData["Ok"]="Venta registrada correctamente y stock actualizado."; return RedirectToAction(nameof(Index));}catch(Exception ex){TempData["Error"]=ex.Message;return RedirectToAction(nameof(Create));}}}
